-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/

-- Wallpaper-derived colours, written by ~/.config/theme/theme-apply.sh.
-- dofile with an absolute path rather than require(), because Hyprland's Lua
-- package.path does not necessarily include ~/.config/hypr. Wrapped in pcall
-- so that a missing or malformed colors.lua degrades to these defaults
-- instead of breaking the entire config.
local colors = (function()
    local ok, generated = pcall(dofile, os.getenv("HOME") .. "/.config/hypr/colors.lua")
    if ok and type(generated) == "table" and generated.active_border then
        return generated
    end
    return {
        active_border   = { colors = {"rgba(33ccffee)", "rgba(00ff99ee)"}, angle = 45 },
        inactive_border = "rgba(595959aa)",
        shadow_color    = 0xee1a1a1a,
    }
end)()

