-- Bind workspaces to monitors.
-- 1-5 live on the ultrawide, 6-10 on the portable panel. Pressing a workspace
-- key that belongs to the other monitor moves focus there automatically.
local workspaceMonitors = {
    { output = "DP-1",     workspaces = { 1, 2, 3, 4, 5 },   default = 1 },
    { output = "HDMI-A-1", workspaces = { 6, 7, 8, 9, 10 },  default = 6 },
}

for _, m in ipairs(workspaceMonitors) do
    for _, ws in ipairs(m.workspaces) do
        hl.workspace_rule({
            workspace  = tostring(ws),
            monitor    = m.output,
            persistent = true,
            default    = (ws == m.default),
        })
    end
end

